  'mcpClient.saveFailed': 'सहेजना विफल रहा। जांचें कि डेमन चल रहा है और फिर प्रयास करें।',
  'useEverywhere.modalAria': 'Open Design हर जगह उपयोग करें',
  'useEverywhere.modalTitle': 'Open Design हर जगह उपयोग करें',
  'useEverywhere.modalSubtitle': 'Open Design को किसी भी IDE, एजेंट या स्क्रिप्ट में डालें — CLI, HTTP, MCP और स्किल। "किसी एजेंट के लिए गाइड कॉपी करें" का उपयोग करें और सब कुछ सेटअप करने के लिए Claude Code, Codex, Cursor, openclaw या hermes में पेस्ट करें।',
  'useEverywhere.closeAria': 'हर जगह उपयोग बंद करें',
