  'chat.example1Tag': 'मैगज़ीन',
  'chat.example1Prompt': 'सीड राउंड जुटाने वाले डिज़ाइन स्टूडियो के लिए 10-स्लाइड एडिटोरियल पिच डेक — Swiss-grid लेआउट, बोल्ड ड्रॉप कैप के साथ बड़े सेरिफ़ हेडलाइन, मोनोस्पेस सेक्शन नंबर, विशाल नेगेटिव स्पेस, और टेक्स्ट-भारी स्लाइड्स के बीच फुल-ब्लीड फ़ोटो स्लाइड्स। कवर, विज़न, मार्केट, प्रोडक्ट, ट्रैक्शन, टीम, आस्क, कॉन्टैक्ट।',
  'chat.example2Title': 'SaaS एनालिटिक्स डैशबोर्ड',
  'chat.example2Tag': 'डेटा',
  'chat.example2Prompt': 'डेवलपर-टूल्स SaaS के लिए घना एनालिटिक्स डैशबोर्ड — सप्ताह-दर-सप्ताह डेल्टा के साथ KPI स्ट्रिप, दो स्टैक्ड लाइन चार्ट (MRR और सक्रिय वर्कस्पेस), उपयोग का विश्व हीटमैप, कोहोर्ट रिटेंशन ग्रिड, टॉप-कस्टमर्स लीडरबोर्ड, और रियल-टाइम इवेंट फ़ीड। डार्क थीम, टैबुलर मोनोस्पेस न्यूमरल, स्पार्कलाइन एक्सेंट।',
  'chat.example3Title': 'वार्षिक रिपोर्ट लॉन्ग-स्क्रॉल',
  'chat.example3Tag': 'एडिटोरियल',
  'chat.example3Prompt': 'क्लाइमेट नॉनप्रॉफ़िट के लिए इंटरैक्टिव वार्षिक रिपोर्ट — लॉन्ग-स्क्रॉल एडिटोरियल लेआउट जिसमें बड़े पुल-कोट ब्लॉक, डेटा विज़ुअलाइज़ेशन (स्टैक्ड बार, एनिमेटेड काउंटर, प्रोजेक्ट साइट्स का कोरोप्लेथ मैप), फ़ोटोग्राफी ब्रेकर, डोनर वॉल, और अंतिम कॉल-टू-एक्शन मिलते हैं। मॉडर्न सेरिफ़ बॉडी, सैंस-सेरिफ़ चार्ट लेबल, अर्द्ध-पेपर पैलेट।',
